package org.brightstats.data;
import java.util.*;import java.nio.file.*;import org.brightstats.stats.*;
public final class ClusterDataChecks {
 static int checks;static void require(boolean value,String label){checks++;if(!value)throw new AssertionError(label);}
 public static void main(String[] args)throws Exception{
  var raw=new DataPreparation.Raw(List.of("ID","Y","Unused"),List.of(List.of("A","1","10"),List.of("A","","11"),List.of("B","3","12"),List.of("B","4","13"),List.of("C","5","14"),List.of("C","6","15")));
  var settings=new DataPreparation.Settings(',',DataPreparation.Decimal.DOT,"",DataPreparation.Missing.MEAN_REPLACEMENT);var definitions=List.of(new DataPreparation.Column("ID",DataPreparation.Kind.TEXT),new DataPreparation.Column("Y",DataPreparation.Kind.NUMERIC),new DataPreparation.Column("Unused",DataPreparation.Kind.NUMERIC));var prepared=DataPreparation.prepare(raw,settings,definitions);var history=ImportHistory.capture("Synthetic clusters",raw,settings,definitions);var model=new SemModel.Model(List.of("Y"),new int[]{0},new double[1][1],new double[][]{{1}},new double[1],List.of(new SemModel.Parameter("Mean",List.of(new SemModel.Location(SemModel.Kind.INTERCEPT,0,0)),0,1)));
  var selected=ClusterData.select(history,prepared.columns(),prepared.values(),0,"ID",model,false);require(selected.ids().equals(List.of("A","A","B","B","C","C")),"Original text cluster labels remain aligned");require(Double.isNaN(selected.data()[1][0]),"Mean replacement is not mistaken for an original observation");require(selected.provenance().sourceRows().equals(List.of(1,2,3,4,5,6)),"All original row identities retained");var complete=ClusterData.select(history,prepared.columns(),prepared.values(),0,"ID",model,true);require(complete.provenance().sourceRows().equals(List.of(1,3,4,5,6))&&complete.provenance().excludedRows()==1,"Explicit complete-case selection retains original row IDs");require(!complete.provenance().selectedDataSha256().equals(selected.provenance().selectedDataSha256()),"Selection changes source identity");var copied=selected.data();copied[0][0]=999;require(selected.data()[0][0]==1,"Selected source data immutable");try{ClusterData.select(history,prepared.columns(),prepared.values(),1,"ID",model,false);throw new AssertionError("Stale source binding accepted");}catch(IllegalArgumentException expected){checks++;}
  List<List<String>> badRows=new ArrayList<>(raw.rows());badRows.set(0,List.of("","1","10"));var badRaw=new DataPreparation.Raw(raw.headers(),badRows);var badHistory=ImportHistory.capture("Missing ID",badRaw,settings,definitions);var badPrepared=DataPreparation.prepare(badRaw,settings,definitions);try{ClusterData.select(badHistory,badPrepared.columns(),badPrepared.values(),0,"ID",model,false);throw new AssertionError("Missing cluster ID silently grouped");}catch(IllegalArgumentException expected){checks++;}var explicit=ClusterData.select(badHistory,badPrepared.columns(),badPrepared.values(),0,"ID",model,true);require(explicit.provenance().sourceRows().equals(List.of(3,4,5,6)),"Missing IDs excluded only by explicit selection");
  Path out=Path.of(args[0]);Files.createDirectories(out);Files.writeString(out.resolve("data-receipt.json"),"{\"checks\":"+checks+"}");System.out.println("Cluster source checks: "+checks);
 }
}
